import{_ as t,o as s,c as o,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/quesion_imgs_93e1144e53594776a940b6a3110a8fcc.CwsRpuOF.png",p="/bzygq/assets/quesion_imgs_7db9d3d686294c7891fd35cd3d593364.Cwka4m7P.png",e="/bzygq/assets/quesion_imgs_b5ee76756fa948b7b63cd9d55ea8e36f.BqTrRtnI.png",m=JSON.parse('{"title":"央企、研究所Java学习路线图","description":"","frontmatter":{},"headers":[],"relativePath":"docs/技术路线&考试路线/6.央企&研究所Java后端技术路线.md","filePath":"docs/技术路线&考试路线/6.央企&研究所Java后端技术路线.md","lastUpdated":1788883925000}'),g={name:"docs/技术路线&考试路线/6.央企&研究所Java后端技术路线.md"};function _(i,a,c,d,v,l){return s(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="央企、研究所java学习路线图" tabindex="-1">央企、研究所Java学习路线图 <a class="header-anchor" href="#央企、研究所java学习路线图" aria-label="Permalink to &quot;央企、研究所Java学习路线图&quot;">​</a></h1><p><strong>学习内容：</strong> Java基础、JVM、Java多线程编程、MySQL、Redis、MyBatis Plus、Spring Boot、分布式/微服务、RocketMQ、OpenFeign、Docker、Git、Maven、计算机基础知识。</p><p><strong>央企集团：</strong> 中国五矿、中国电科、中国兵器、中航工业、铁路局、南方电网、国家电网、中国商飞、中国通号、五大行....太多了，列举不完。</p><p><strong>Java项目：Java后台项目</strong></p><p>这个路线图不仅仅是现在大型央企、国企研究所Java相关岗位用到的技术栈，也是主流私企、互联网用到的，大家直接先看图，完事之后讲几个问题：</p><p><img src="'+n+'" alt=""></p><h1 id="央企研究所java研发主要做什么" tabindex="-1">央企研究所Java研发主要做什么？ <a class="header-anchor" href="#央企研究所java研发主要做什么" aria-label="Permalink to &quot;央企研究所Java研发主要做什么？&quot;">​</a></h1><p><img src="'+p+'" alt=""></p><p>相信大家无论是在网络上，或者是在学校里面，关于Java了解的更多的是去互联网大厂或者一些小私企，对于Java在央国企里面能做什么知之甚少。</p><p>实际上，近些年来由于互联网的下行，以前网上传播的什么35岁就被淘汰找不到工作已经变得过于乐观了，现在<strong>很多互联网大厂普通员工，32岁甚至30岁就会被淘汰。</strong></p><p>并且随着AI的广泛使用，现在互联网大厂和私企对程序员的需求是逐年走低的，叠加以前培训班疯狂量产的程序员，这个时候再<strong>去私企、互联网大厂做程序员实际上并不是一个好的选择</strong>。</p><p>而众所不周知的是<strong>央企和研究所也会招聘大量的Java开发程序员</strong>，来负责<strong>内部系统、上级央企集团的业务</strong>或者是一些科研项目的开发。例如：</p><p><strong>中国石油、中国五矿、中国稀土</strong>等资源型的央企都在做数字化转型，很多<strong>油田、矿山工厂、冶炼厂</strong>等都需要做物联网平台建设项目，所以Java后台在这些央企多半是做物联网相关的平台开发工作。</p><p><strong>中国建筑、中国电建、中国铁建</strong>等建筑类央企，同样会做数字化转型相关的业务，对于房建、公路和铁路等场景针对性的开发一些物联网的相关平台运用。</p><p><strong>五大行、中国人保、中国人寿</strong>等金融类央企则是开发to C的相关应用，这也是招聘Java程序员比较多的一个方向，开发的内容也是大家平时用到的金融类的app。</p><p>当然，大量的央企会有一部分业务是找外包公司来完成的，所以进去只承担项目经理的角色即可，但是也有一部分研发单位是需要自己开发和写代码的，这种一般偏向于社招。</p><h1 id="央企、研究所java研发工资真的很低吗" tabindex="-1">央企、研究所Java研发工资真的很低吗？ <a class="header-anchor" href="#央企、研究所java研发工资真的很低吗" aria-label="Permalink to &quot;央企、研究所Java研发工资真的很低吗？&quot;">​</a></h1><p><img src="'+e+'" alt=""></p><p>很多人说到央企、国企的研发，第一印象就是工资很低，实际上虽然工资待遇比不上互联网大厂，但是在二线城市来说好好生活并不成问题，一线城市的央企由于工资太低，确实需要慎重考虑才行。</p><p>并且，由于互联网大厂、私企的加班较多，并且稳定性相对较差，因此央企、国企的Java开发时薪相对较高，如果是央企的正式员工的话，职业生涯也会更长，无需担心35岁中年危机的问题。</p><p>例如<strong>中国商飞对于校招信息技术岗的应届生工资就可以开到21w的总包</strong>，而南网数字集团的应届生工资也能达到25w左右，虽然比起互联网大厂的头部offer什么50w~60w的总包确实少很多，但是考虑到工作强度和稳定性也是非常值得考虑的。</p><p>除此之外，<strong>央企的公积金一般都按照12%的比例缴纳</strong>，同时还会有企业年金、补充医疗保险等，这些东西虽然大厂也有，但是<strong>缴纳15年社保和缴纳30年社保是2个不同的概念</strong>。</p><h1 id="央企、研究所java研发的难度怎么样" tabindex="-1">央企、研究所Java研发的难度怎么样？ <a class="header-anchor" href="#央企、研究所java研发的难度怎么样" aria-label="Permalink to &quot;央企、研究所Java研发的难度怎么样？&quot;">​</a></h1><p>由于央企、国企研发的软件一般是内部使用为主，即使是类似于中国五矿研发的矿山管理系统，也是一个矿山、冶炼厂单独一套软件，所以使用的体量不会特别大，甚至某些<strong>央企内部研发的软件只有一个部门几十上百号人使用</strong>。</p><p>所以体量决定了央企、研究所里面的<strong>Java研发所涉及到的技术难度不会太大，同时线上压力非常小、加班也非常少</strong>（除非碰到比较变态的领导）。</p><p>有的人可能会说，用户量这么少，根本没有技术含量，技术不能成长，我这辈子就废了。实际上这是一种很严重的学生思维，工作几年的人只想着早点儿干完活儿下班，而且想学技术可以去华为OD，为的就是这块儿技术。</p><p>实际上，技术再好没有需求场景也并不能给你带来收益，并且现在无论是什么<strong>Java开发、C++开发都不存在特别高深的技术</strong>，都是前人已经做好的方案，并没有太多的创新，即使去大厂也是ppt雕花。</p><p>所以，业务简单，工资待遇还可以，稳定性好，早点儿下班儿比什么都强，同时对于技术能力不是很强的同学，央企、研究所更是你的天堂，一般领导对于新人都会给出很长的时间和周期来让你学习。</p><p>所以，央企国企的研发岗，综合性价比更高。</p>',29)])])}const h=t(g,[["render",_]]);export{m as __pageData,h as default};
